CREATE TABLE "communications" ("id" UUID NOT NULL,"contact_id" UUID NOT NULL,"author_user_id" UUID NOT NULL,"type" VARCHAR(16) NOT NULL DEFAULT 'Email',"subject" VARCHAR(200) NOT NULL,"body" VARCHAR(10000) NOT NULL,"status" VARCHAR(16) NOT NULL DEFAULT 'Draft',"sent_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "communications_pkey" PRIMARY KEY ("id"),CONSTRAINT "communications_contact_id_fkey" FOREIGN KEY ("contact_id") REFERENCES "contacts"("id") ON DELETE CASCADE,CONSTRAINT "communications_author_user_id_fkey" FOREIGN KEY ("author_user_id") REFERENCES "users"("id"));
CREATE INDEX "communications_contact_id_idx" ON "communications"("contact_id");CREATE INDEX "communications_status_idx" ON "communications"("status");CREATE INDEX "communications_subject_idx" ON "communications"("subject");
